def _apply(r):
    u = UPDATES.get(f"{r[0]}-{r[1]}")
    if not u: return r
    r = list(r); r[12], r[13], r[14], r[15] = u[0], u[1], u[2], u[3]; r[4] = f"{r[4]} [Update 2026-11-10: {u[4]}]"
    return tuple(r)
R = [_apply(r) for r in R]


FIELDS = ['id', 'module', 'title', 'business_objective', 'description', 'user_roles', 'preconditions', 'trigger', 'main_workflow', 'alternative_workflow', 'business_rules', 'data_fields', 'validations', 'permissions', 'notifications', 'audit', 'reports_dashboard_impact', 'integration', 'error_scenarios', 'acceptance_criteria', 'priority', 'dependencies', 'implementation_status', 'api', 'ui', 'tests', 'baseline_id', 'baseline_classification']

# Test IDs that are backed by automated tests in backend/test (see docs/testing/TEST_PLAN.md)
AUTOMATED = {'TC-SEC-001..004','TC-SEC-RBAC-*','TC-PLT-003','TC-AUD-001..002','TC-SEC-OPT','TC-WF-001..002','TC-WF-001','TC-WF-002','TC-GOV-001..006','TC-GOV-001','TC-GOV-005','TC-PLT-008','TC-SEC-RBAC-restricted','TC-SEC-VAL','TC-PLT-VAL','TC-RPT-OKR','TC-FIN-003','TC-RPT-001','TC-RPT-DOC','TC-PRD-001','TC-PRD-002','TC-FIN-001, TC-RPT-001','TC-AI-001','TC-AI-002','TC-AI-003','TC-CALC-RICE','TC-CALC-RQ','TC-BIA-001','TC-BIA-002','TC-BIA-003','TC-BIA-004','TC-WRK-001','TC-CALC-LOAD','TC-FIN-002','TC-FIN-004','TC-CHG-001','TC-REL-001','TC-REL-001..002','TC-REL-003','TC-VND-003','TC-INT-001','TC-INT-002','TC-SEC-*','TC-RPT-HEAT','TC-UX-MOB'}

def expand(r):
  m, n, title, obj, desc, trig, flow, rules, fields, ac, pri, deps, status, api, ui, tests = r
  name, roles, notif, integ, rep = MODULES[m]
  rid = f'FR-{m}-{n}'
  return {
    'id': rid, 'module': name, 'title': title, 'business_objective': obj, 'description': desc, 'user_roles': roles,
    'preconditions': 'User authenticated with required permission; parent records exist in the same organisation' if m != 'NFR' else 'n/a',
    'trigger': trig, 'main_workflow': flow,
    'alternative_workflow': 'Validation or business-rule failure returns the record unchanged with field-level messages; user corrects and resubmits' if m != 'NFR' else 'n/a',
    'business_rules': rules, 'data_fields': fields,
    'validations': 'Server-side schema validation (types, enums, ranges, required), reference integrity within organisation, unknown fields rejected' if m != 'NFR' else 'n/a',
    'permissions': f'{m.lower()} resources: read/write/delete per role; governed transitions via approval only' if m not in ('NFR',) else 'n/a',
    'notifications': notif, 'audit': 'Create/update/delete/transition events with actor, before/after and hash chain' if m != 'NFR' else 'n/a',
    'reports_dashboard_impact': rep, 'integration': integ,
    'error_scenarios': '400 validation; 403 permission; 404 not found/not visible; 409 version conflict; 422 business rule (e.g. gate criteria, guarded status)' if m != 'NFR' else 'n/a',
    'acceptance_criteria': ac, 'priority': pri, 'dependencies': deps if deps == '-' else ', '.join(f'FR-{d}' for d in deps.split(', ')),
    'implementation_status': status, 'api': api, 'ui': ui, 'tests': tests if tests in AUTOMATED or tests == '-' else f'{tests} (manual / not yet automated)',
    'baseline_id': 'Pending FRS v1.1 import', 'baseline_classification': 'New (gap-derived) – reconcile on import',
  }

def main():
  rows = [expand(r) for r in R]
  with open(os.path.join(HERE, 'REQUIREMENTS_TRACEABILITY.csv'), 'w', newline='') as f:
    w = csv.DictWriter(f, fieldnames=FIELDS); w.writeheader(); w.writerows(rows)
  try:
    import openpyxl
    from openpyxl.styles import Font, PatternFill, Alignment
    wb = openpyxl.Workbook(); ws = wb.active; ws.title = 'Traceability'
    ws.append(FIELDS)
    for r in rows: ws.append([r[k] for k in FIELDS])
    for c in ws[1]: c.font = Font(bold=True, color='FFFFFF'); c.fill = PatternFill('solid', fgColor='2747D6')
    ws.freeze_panes = 'C2'
    for col in ws.columns: ws.column_dimensions[col[0].column_letter].width = 18 if col[0].value not in ('description', 'acceptance_criteria', 'business_rules') else 60
    for row in ws.iter_rows(min_row=2):
      for c in row: c.alignment = Alignment(wrap_text=True, vertical='top')
    s = wb.create_sheet('Summary')
    s.append(['Module', 'Requirements', 'Implemented', 'Partial', 'Planned'])
    for m, (name, *_ ) in MODULES.items():
      sub = [r for r in rows if r['module'] == name]
      s.append([name, len(sub), sum(r['implementation_status'].startswith('Implemented') for r in sub), sum(r['implementation_status'] == 'Partial' for r in sub), sum(r['implementation_status'] == 'Planned' for r in sub)])
    wb.save(os.path.join(HERE, 'REQUIREMENTS_TRACEABILITY.xlsx'))
  except ImportError:
    print('openpyxl not installed – XLSX skipped')

  out = ['# Master Functional Requirements Specification (MASTER_FRS)', '',
         '_Generated from `requirements_source.py` – edit the source, not this file._', '',
         '> **Baseline status:** the existing FRS v1.1 (with Product Management addendum) was not available in this session. This specification was derived from online research, the master prompt and professional assessment. On receipt of v1.1, each original requirement will be imported, keep its original ID in `baseline_id`, and be classified (Retained / Enhanced / Expanded / Replaced / Deferred / Rejected) – see REQUIREMENT_GAP_REGISTER.md.', '',
         '## Summary', '', '| Module | Requirements | Implemented | Partial | Planned |', '|---|---|---|---|---|']
  for m, (name, *_ ) in MODULES.items():
    sub = [r for r in rows if r['module'] == name]
    out.append(f"| {name} | {len(sub)} | {sum(r['implementation_status'].startswith('Implemented') for r in sub)} | {sum(r['implementation_status'] == 'Partial' for r in sub)} | {sum(r['implementation_status'] == 'Planned' for r in sub)} |")
  out += ['', f'Total requirements: **{len(rows)}**. “Implemented” means code, API, UI and automated tests exist in this repository (see `tests` column); it does not mean production-accepted.', '']
  cur = None
  for r in rows:
    if r['module'] != cur:
      cur = r['module']; out += ['', f'## {cur}', '']
    out += [f"### {r['id']} – {r['title']}", '', '| Attribute | Specification |', '|---|---|']
    for k in FIELDS[3:]:
      out.append(f"| {k.replace('_', ' ').capitalize()} | {str(r[k]).replace('|', '/')} |")
    out.append('')
  open(os.path.join(HERE, 'MASTER_FRS.md'), 'w').write('\n'.join(out))
  print(f'{len(rows)} requirements written')

if __name__ == '__main__':
  main()
